// Started requests: look for the run each one produced.
const open = $('Open requests').first().json;
const requests = Array.isArray(open.requests) ? open.requests : JSON.parse(open.requests || '[]');
return requests.filter((r) => r.state === 'dispatched' && r.dispatched_at)
  .map((r) => ({ json: { ...r, since: new Date(Date.parse(r.dispatched_at) - 120000).toISOString().slice(0, 19) + 'Z' } }));

// The run W1 started has the title "<workflow> <ticket>" (run-name) and was
// created after the start. Only finished runs have a run-outcome to read.
const requests = $('Dispatched').all();
return $input.all().flatMap((page, i) => {
  const r = requests[i].json;
  const run = (page.json.workflow_runs ?? [])
    .filter((w) => w.display_title === `${r.workflow} ${r.ticket}` && w.created_at >= r.since)
    .sort((a, b) => b.created_at.localeCompare(a.created_at))[0];
  return run && run.status === 'completed' ? [{ json: { request_id: r.id, run_id: run.id } }] : [];
});

// Requests blocked because their cases weren't merged: are they now?
const open = $('Open requests').first().json;
const requests = Array.isArray(open.requests) ? open.requests : JSON.parse(open.requests || '[]');
return requests.filter((r) => r.state === 'blocked' && r.reason === 'cases-not-merged').map((r) => ({ json: r }));

// One decision per request that changed (Story 5.5). Records are `done` only
// when the run's PR or run-outcome is seen; a request without one is tried
// again, at most MAX_TRIES times. Every notice goes out once (`notified`).
const MAX_TRIES = 3;
const LOST_AFTER_MS = 20 * 60000;
const now = new Date();
const istDay = (d) => new Date(d.getTime() + 330 * 60000).toISOString().slice(0, 10);
const nextIstMidnight = (d) => {
  const ist = new Date(d.getTime() + 330 * 60000);
  return new Date(Date.UTC(ist.getUTCFullYear(), ist.getUTCMonth(), ist.getUTCDate() + 1) - 330 * 60000).toISOString();
};
const list = (name) => ($(name).isExecuted ? $(name).all().map((i) => i.json) : []);
const open = $('Open requests').first().json;
const s11 = typeof open.s11 === 'string' ? JSON.parse(open.s11) : (open.s11 ?? {});
const casesPrs = typeof open.cases_prs === 'string' ? JSON.parse(open.cases_prs) : (open.cases_prs ?? {});

const outcomes = Object.fromEntries(list('Read outcome').map((o) => o.data).filter((o) => o && o.run_id).map((o) => [o.run_id, o]));
const finished = Object.fromEntries(list('Finished runs').map((f) => [f.request_id, f.run_id]));
const casesNow = list('Cases on main?').map((c, i) => [list('Waiting for cases')[i], c.statusCode === 200]);

const decisions = [];
const decide = (r, d) => decisions.push({
  request_id: r.id, ticket: r.ticket, workflow: r.workflow, state: r.state, reason: r.reason ?? '',
  run_id: null, pr_url: '', notice: '', notified: r.notified, enqueue: '', not_before: now.toISOString(),
  cases_pr: casesPrs[r.ticket] ?? '', ...d,
});
const retryOrFail = (r, why, runId = null) => (r.attempts < MAX_TRIES
  ? decide(r, { state: 'deferred', reason: why, run_id: runId, enqueue: 'retry' })
  : decide(r, { state: 'failed', reason: why, run_id: runId, notice: 'S10',
    notified: `failed:${why}` }));

const pages = list('List runs');
list('Dispatched').forEach((r, i) => {
  const runId = finished[r.id];
  if (!runId) {
    // Still running: wait. No run with its title 20 minutes after the start: lost, start it again.
    const runs = pages[i]?.workflow_runs ?? [];
    const anyRun = runs.some((w) => w.display_title === `${r.workflow} ${r.ticket}` && w.created_at >= r.since);
    if (!anyRun && now - Date.parse(r.dispatched_at) > LOST_AFTER_MS) retryOrFail(r, 'run-not-found');
    return;
  }
  const o = outcomes[runId];
  if (!o) { retryOrFail(r, 'no-run-outcome', runId); return; }
  if (o.status === 'ok') {
    const notice = o.pr_url && r.notified !== o.pr_url ? (r.workflow === 'draft-cases' ? 'S7' : 'S9') : '';
    decide(r, { state: 'done', reason: o.reason ?? '', run_id: runId, pr_url: o.pr_url ?? '', notice,
      notified: o.pr_url || r.notified });
  } else if (o.status === 'blocked' && o.reason === 'cases-already-on-main') {
    decide(r, { state: 'done', reason: o.reason, run_id: runId });
  } else if (o.status === 'blocked') {
    const key = `blocked:${o.reason}`;
    decide(r, { state: 'blocked', reason: o.reason, run_id: runId, notice: r.notified === key ? '' : 'S10', notified: key });
  } else if (o.status === 'capped') {
    const today = istDay(now);
    decide(r, { state: 'deferred', reason: 'capped', run_id: runId, enqueue: 'capped', not_before: nextIstMidnight(now),
      notice: s11[r.workflow] === today ? '' : 'S11', s11_day: today });
  } else if (o.status === 'disabled') {
    decide(r, { state: 'deferred', reason: 'disabled', run_id: runId, enqueue: 'disabled' });
  } else {
    retryOrFail(r, o.reason || 'error', runId);
  }
});

// Blocked until the cases were merged: once they are, start it again.
for (const [r, merged] of casesNow) {
  if (merged) decide(r, { state: 'deferred', reason: 'cases-merged', enqueue: 'retry' });
}

// One S11 per workflow per day, even when several runs ended capped.
const s11Sent = new Set();
for (const d of decisions) {
  if (d.notice === 'S11') {
    if (s11Sent.has(d.workflow)) d.notice = '';
    s11Sent.add(d.workflow);
  }
}
return decisions.map((d) => ({ json: d }));

// Only decisions that post a notice; their case file gives the flows.
return $input.all().filter((d) => d.json.notice).map((d) => ({ json: { ...d.json,
  case_ref: d.json.notice === 'S7' ? `agent/${d.json.ticket}-cases` : 'main' } }));

// S7, S9, S10 and S11 (EXPERIENCE.md M7, M9, M10, M11).
const settings = $('Settings').first().json;
const repo = `https://github.com/${settings.repo}`;
const jiraLink = (key) => ({ label: `Jira ${key}`, url: `${settings.jira_url}/browse/${key}` });
const flowsOf = (file) => {
  if (file.statusCode !== 200 || !file.body?.content) return [];
  const text = atob(file.body.content.replace(/\s/g, ''));
  const match = text.match(/^flows:\s*\[([^\]]*)\]/m);
  return match ? match[1].split(',').map((f) => f.trim()).filter(Boolean) : [];
};
const code = (items) => items.map((f) => `\`${f}\``).join(', ');
const WORK = { 'draft-cases': 'Case drafting', 'generate-tests': 'Test generation' };
const PLAIN = {
  'cases-not-merged': ['its cases PR is not merged on `main`', 'review and merge PR 1. This retries on its own after that.'],
  'no-matching-flow': ['no flow in the flow list fits this ticket', 'choose a flow, or ask the QA lead to add one, then start draft-cases again.'],
  'no-acceptance-criteria': ['the ticket has no acceptance criteria', 'add acceptance criteria to the ticket, then start draft-cases again.'],
  'cannot-automate': ['a case can\'t be tested with the existing helpers', 'adjust the case file, or write that test by hand.'],
  'case-file-unusable': ['the case file can\'t be used as it is', 'fix the case file in a PR, then start generate-tests again.'],
};
const S11_WORK = {
  'draft-cases': ['Case drafting', 'case drafts', (t) => `${t} will be drafted after 00:00 IST.`, 'run /draft-cases in Claude Code on a laptop, or ask the QA lead to change the limit.'],
  'generate-tests': ['Test generation', 'test generations', (t) => `Tests for ${t} will be generated after 00:00 IST.`, 'run /generate-api-tests in Claude Code on a laptop, or ask the QA lead to change the limit.'],
};

const notices = $('Notices').all();
return $input.all().map((file, i) => {
  const d = notices[i].json;
  const flows = flowsOf(file.json);
  let m;
  if (d.notice === 'S7') {
    m = { kind: '', header: `Test cases drafted for ${d.ticket}`,
      body: `The agent drafted cases from the acceptance criteria.${flows.length ? ` Flows: ${code(flows)}.` : ''}`,
      todo: 'review and edit PR 1, then merge it to accept the cases.',
      links: [{ label: 'PR 1', url: d.pr_url }, jiraLink(d.ticket),
        { label: 'Case file', url: `${repo}/blob/${d.case_ref}/cases/${d.ticket}.md` }] };
  } else if (d.notice === 'S9') {
    m = { kind: '', header: `Tests generated for ${d.ticket}`,
      body: `PR 2 adds API tests with SQL checks${flows.length ? ` for flow ${code(flows)}` : ''}.`,
      todo: 'review every line, approve, then start `uat-pr` with the reviewed commit SHA.',
      links: [{ label: 'PR 2', url: d.pr_url }, { label: 'Run workflow: uat-pr', url: `${repo}/actions/workflows/uat-pr.yml` },
        jiraLink(d.ticket)] };
  } else if (d.notice === 'S11') {
    const [work, units, later, urgent] = S11_WORK[d.workflow];
    m = { kind: 'info', header: `${work} waits until tomorrow`,
      body: `The agent's own check found today's limit of ${units} reached (counted since 00:00 IST).\n${later(d.ticket)}`,
      todo: urgent, todo_label: 'If urgent', links: [jiraLink(d.ticket)] };
  } else {
    const failed = d.state === 'failed';
    const [why, todo] = PLAIN[d.reason] ?? [failed ? `it failed ${3} times` : 'the agent stopped', failed
      ? `look at the last run, or run ${d.workflow === 'draft-cases' ? '/draft-cases' : '/generate-api-tests'} ${d.ticket} on a laptop.`
      : 'look at the run, then start it again.'];
    const header = d.reason === 'cases-not-merged'
      ? `tests for ${d.ticket} can't be generated yet`
      : `${WORK[d.workflow]} for ${d.ticket} ${failed ? 'failed' : 'stopped'}`;
    const links = [];
    if (d.reason === 'cases-not-merged' && d.cases_pr) links.push({ label: 'PR 1', url: d.cases_pr });
    if (d.run_id) links.push({ label: 'Run', url: `${repo}/actions/runs/${d.run_id}` });
    links.push(jiraLink(d.ticket));
    m = { kind: 'action', header, body: `Reason: ${why} (\`${d.reason}\`).`, todo, links };
  }
  return { json: { todo_label: '', thread_ts: '', ...m } };
});

// A notice Slack didn't take fails the run (W0 alerts); nothing is saved, so
// it is tried again on the next run.
for (const r of $input.all()) {
  if (!r.json.posted && !r.json.preview) throw new Error(`W1 notice not posted: ${r.json.error}`);
}
return [{ json: { notices: $input.all().length } }];

// One audit entry per decision.
return $('Decide').all().map((d) => ({
  json: {
    actor: 'n8n:w1-follow-up',
    actor_type: 'n8n',
    action: `follow-up-${d.json.state}${d.json.notice ? `-${d.json.notice.toLowerCase()}` : ''}`,
    target: `${d.json.workflow} ${d.json.ticket}${d.json.reason ? ` (${d.json.reason})` : ''}`,
    link: d.json.pr_url || (d.json.run_id ? `https://github.com/${$('Settings').first().json.repo}/actions/runs/${d.json.run_id}` : ''),
  },
}));
